-- The two Zumba SPECIALs on Monday 16 Nov 2026 (guests from Olomouc) are always paid for: no welcome lesson, card
-- lesson or other free entry, no intro price. The clients read it in the lesson's note too (unless it was edited).
UPDATE "class_sessions" SET "no_free_entry" = true
WHERE "id" IN ('5ea2983c-b146-45ae-b4b6-f86c43acc4c4', '00d2c63c-54d6-4248-a5a0-842b458b2e96') AND "title" LIKE '%SPECIAL';
